<script lang="ts">
	import { onMount } from 'svelte';
	import { RefreshCw, Archive, Activity, Trash2, FileCheck, Image } from '@lucide/svelte';
	import Button from '$lib/components/ui/button/button.svelte';
	import { tr } from './preferences.svelte';
	type Target={projectId:string;id:string;messageId?:string};
	type PendingEffect={type:'restore'|'trash'|'pin'|'remove'|'rename';projectId:string;chatId?:string;messageId?:string;actionId?:string;id?:string;path?:string;hash?:string;backupId?:string;kind?:string;title?:string};
	let { request, projectId, chat, instanceId='companion', onConversationChange, onNavigate, onImages }: {request:(route:string,options?:RequestInit)=>Promise<any>;projectId:string;chat?:any;instanceId?:string;language?:'fr'|'en';onConversationChange?:(next:any|null)=>void|Promise<void>;onNavigate?:(target:Target)=>void|Promise<void>;onImages?:()=>void;}=$props();
	let tab=$state<'activity'|'deliverables'|'trash'|'actions'>('activity'),busy=$state(false),loading=$state(false),failure=$state(''),notice=$state('');
	let events=$state<any[]>([]),deliverables=$state<any[]>([]),trash=$state<any[]>([]),detail=$state<any>(null),detailTitle=$state(''),selectedMessageId=$state(''),pinTitle=$state('');
	let activityCursor=$state<string|null>(null),partial=$state(''),diffs=$state<Record<string,any>>({}),pending=$state<PendingEffect|null>(null),seen=$state<Record<string,number>>({}),since=$state(Date.now()),initialized=$state(false);
	let sequence=0,loadedProject='',loadedInstance='';
	const query=(route:string,values:Record<string,string>)=>route+'?'+new URLSearchParams(values);
	const effectKey=(pid=projectId)=>`bionic:workspace-pending:${instanceId}:${pid}`;
	const seenKey=()=>`bionic:activity-seen:${instanceId}`;
	const responses=$derived((chat?.messages||[]).filter((message:any)=>message.role==='assistant'&&message.text?.trim()));
	const actionRows=$derived((chat?.messages||[]).flatMap((message:any)=>[...(message.actions||[]).map((action:any)=>({message,action,historical:false})),...(message.historicalActions||[]).map((action:any)=>({message,action,historical:true}))]));
	const uncertainWrites=$derived((chat?.messages||[]).flatMap((message:any)=>(message.mutationIntents||[]).filter((intent:any)=>intent.status==='uncertain').map((intent:any)=>({message,intent}))));
	const date=(value:any)=>{const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'—':parsed.toLocaleString(tr('fr-FR','en-GB'),{dateStyle:'medium',timeStyle:'short'});};
	function outcome(value:string){const labels:Record<string,string>={completed:tr('Terminée','Completed'),stopped:tr('Arrêtée','Stopped'),error:tr('En échec','Failed'),interrupted:tr('Interrompue','Interrupted')};return labels[value]||value;}
	const isUnread=(event:any)=>event.finishedAt>=since&&!seen[event.id];
	const safeAction=(row:any)=>!row.historical&&!row.action.historical&&!row.message.fromFork&&!chat?.readOnly&&chat?.source!=='bionic'&&row.action.ok===true&&(!row.action.projectId||row.action.projectId===projectId);
	function saveSeen(){try{localStorage.setItem(seenKey(),JSON.stringify({since,seen:Object.fromEntries(Object.entries(seen).slice(-500))}));}catch{notice=tr('Le suivi de lecture restera limité à cette page.','Read status will remain limited to this page.');}}
	function markRead(item:any){seen={...seen,[item.id]:Date.now()};saveSeen();}
	function markAll(){since=Date.now();seen={};saveSeen();}
	function remember(effect:PendingEffect){sessionStorage.setItem(effectKey(effect.projectId),JSON.stringify(effect));pending=effect;}
	function clearEffect(effect:PendingEffect){sessionStorage.removeItem(effectKey(effect.projectId));if(effect.projectId===projectId)pending=null;}
	async function loadActivity(append=false){const token=sequence;const result=await request(query('/api/activity',{limit:'100',...(append&&activityCursor?{cursor:activityCursor}:{})}));if(token!==sequence)return;const known=new Set(events.map(item=>item.id));events=append?[...events,...(result.events||[]).filter((item:any)=>!known.has(item.id))]:result.events||[];activityCursor=result.nextCursor||null;partial=result.partial?(result.warnings||[]).map((item:any)=>item.message).join(' ')||tr('Activité partiellement disponible.','Activity is partially available.'):'';}
	async function loadCopies(){const pid=projectId,token=sequence;const result=await request(query('/api/deliverables',{projectId:pid}));if(pid===projectId&&token===sequence)deliverables=result.deliverables||[];}
	async function loadTrash(){const pid=projectId,token=sequence;const result=await request(query('/api/files/trash',{projectId:pid}));if(pid===projectId&&token===sequence){trash=result.items||[];if(result.warnings?.length)partial=result.warnings.map((item:any)=>item.message).join(' ');}}
	async function refreshChat(id=chat?.id,pid=projectId){if(!id)return;const token=sequence;const next=await request(query('/api/conversation',{projectId:pid,id,limit:'100'}));if(pid===projectId&&token===sequence&&id===chat?.id)await onConversationChange?.(next);return next;}
	async function refresh(force=false){if(loading&&!force)return;const token=sequence;loading=true;failure='';try{await Promise.all([loadActivity(),loadCopies(),loadTrash()]);}catch(error:any){if(token===sequence)failure=error.message||tr('Impossible de charger l’espace du projet.','Unable to load the project workspace.');}finally{if(token===sequence)loading=false;}}
	async function initialize(pid:string){loadedProject=pid;loadedInstance=instanceId;++sequence;detail=null;deliverables=[];trash=[];diffs={};failure='';notice='';pending=null;try{const saved=JSON.parse(sessionStorage.getItem(effectKey(pid))||'null');if(saved?.projectId===pid&&['restore','trash','pin','remove','rename'].includes(saved.type))pending=saved;}catch{}if(pid)await refresh(true);}
	async function openCopy(item:any){if(busy)return;busy=true;failure='';const pid=projectId,token=sequence;try{const result=await request(query('/api/deliverable',{projectId:pid,id:item.id}));if(pid===projectId&&token===sequence){detail=result;detailTitle=result.title;}}catch(error:any){failure=error.message;}finally{busy=false;}}
	async function effectCall(effect:PendingEffect,route:string,body:any,after:()=>Promise<void>){
		if(busy||pending)return;busy=true;failure='';notice='';let submitted=false;
		try{remember(effect);submitted=true;await request(route,{method:'POST',body:JSON.stringify(body)});clearEffect(effect);if(effect.projectId===projectId){await after();notice=tr('Action confirmée par le serveur.','Action confirmed by the server.');}}
		catch(error:any){if(error?.status>=400&&error.status<500&&pending)clearEffect(effect);failure=(error.message||tr('Résultat non confirmé.','Result unconfirmed.'))+(submitted&&pending?tr(' Relis le serveur avant toute nouvelle action.',' Read the server state before taking another action.'):'');}
		finally{busy=false;}
	}
	async function pin(message:any,action?:any){if(!chat?.id)return;const effect:PendingEffect={type:'pin',projectId,chatId:chat.id,messageId:message.id,kind:action?'file':'message',...(action?{actionId:action.id}:{})};await effectCall(effect,'/api/deliverables',{projectId,chatId:chat.id,messageId:message.id,kind:effect.kind,...(action?{actionId:action.id}:{}),...(pinTitle.trim()?{title:pinTitle.trim()}:{})},async()=>{await loadCopies();tab='deliverables';});}
	async function renameCopy(){if(!detail||!detailTitle.trim())return;const effect:PendingEffect={type:'rename',projectId,id:detail.id,title:detailTitle.trim()};await effectCall(effect,'/api/deliverable/rename',{projectId,id:detail.id,title:effect.title},async()=>{detail={...detail,title:effect.title};await loadCopies();});}
	async function removeCopy(){if(!detail||!window.confirm(tr('Retirer cette copie de l’étagère ? Le fichier du projet et la conversation restent conservés.','Remove this saved copy? The project file and conversation are retained.')))return;const id=detail.id;await effectCall({type:'remove',projectId,id},'/api/deliverable/remove',{projectId,id},async()=>{detail=null;await loadCopies();});}
	async function compare(row:any){if(busy||!safeAction(row))return;busy=true;failure='';try{const result=await request('/api/files/action-diff',{method:'POST',body:JSON.stringify({projectId,sessionId:chat.id,messageId:row.message.id,actionId:row.action.id})});diffs={...diffs,[row.action.id]:result};}catch(error:any){failure=error.message;}finally{busy=false;}}
	async function restoreAction(row:any){
		if(!safeAction(row)||row.action.restored)return;const action=row.action;
		if(!window.confirm(tr('Rétablir la version précédente de ','Restore the previous version of ')+action.path+tr(' ? Le serveur vérifiera la version actuelle avant tout remplacement.','? The server will verify the current version before replacing it.')))return;
		const effect:PendingEffect={type:'restore',projectId,chatId:chat.id,messageId:row.message.id,actionId:action.id,path:action.path,hash:action.hash,backupId:action.backupId};
		const isTrash=!!action.trashId;
		await effectCall(effect,isTrash?'/api/file/restore-trash':'/api/file/restore',isTrash?{projectId,chatId:chat.id,actionId:action.id}:{projectId,chatId:chat.id,actionId:action.id,rootId:'project',path:action.path,hash:action.hash,backupId:action.backupId},async()=>{await refreshChat();await loadTrash();});
	}
	async function restoreTrash(item:any){if(!window.confirm(tr('Restaurer ','Restore ')+item.path+tr(' sans remplacer un fichier existant ?',' without replacing an existing file?')))return;await effectCall({type:'trash',projectId,id:item.id,path:item.path,hash:item.hash},'/api/files/trash/restore',{projectId,backupId:item.id},async()=>{await loadTrash();});}
	async function recover(){const effect=pending;if(!effect||busy)return;busy=true;failure='';try{
		if(effect.type==='restore'){
			const current=await refreshChat(effect.chatId,effect.projectId),action=current?.messages?.flatMap((message:any)=>message.actions||[]).find((item:any)=>item.id===effect.actionId);
			if(action?.restored){clearEffect(effect);notice=tr('Restauration confirmée après relecture.','Restoration confirmed after reading the server.');}
			else{const file=await request(query('/api/file',{projectId:effect.projectId,rootId:'project',path:effect.path||''}));if(file.hash===effect.hash){clearEffect(effect);notice=tr('La version initiale est toujours présente. Aucun remplacement relancé.','The initial version is still present. Replacement was not sent again.');}else notice=tr('Le fichier a changé ; l’effet reste incertain. Télécharge les versions et vérifie-les avant toute autre restauration.','The file changed; the effect remains uncertain. Download and compare versions before another restoration.');}
		}else if(effect.type==='trash'){
			try{const file=await request(query('/api/file',{projectId:effect.projectId,rootId:'project',path:effect.path||''}));if(file.hash===effect.hash){clearEffect(effect);notice=tr('Le fichier restauré est présent et son empreinte correspond.','The restored file is present and its hash matches.');}else notice=tr('Un fichier différent est présent. Aucune restauration renvoyée.','A different file is present. Restoration was not sent again.');}catch(error:any){if(error.status===404){clearEffect(effect);notice=tr('Le fichier est absent ; aucune restauration relancée.','The file is absent; restoration was not sent again.');}else throw error;}
		}else{
			const result=await request(query('/api/deliverables',{projectId:effect.projectId}));const copies=result.deliverables||[];
			const found=effect.type==='pin'?copies.find((item:any)=>item.kind===effect.kind&&item.origin?.chatId===effect.chatId&&item.origin?.messageId===effect.messageId&&(!effect.actionId||item.origin?.actionId===effect.actionId)):copies.find((item:any)=>item.id===effect.id);
			if(effect.type==='remove'&&!found||effect.type==='rename'&&found?.title===effect.title||effect.type==='pin'&&found){clearEffect(effect);notice=tr('État retrouvé sur le serveur, sans nouvel envoi.','Server state recovered without sending again.');}
			else{clearEffect(effect);notice=tr('Modification non retrouvée. Aucun nouvel envoi automatique ; vérifie les copies affichées.','Change not found. Nothing was sent again automatically; check the displayed copies.');}
		}
		await Promise.all([loadCopies(),loadTrash()]);
	}catch(error:any){failure=error.message||tr('Relecture impossible. Aucun nouvel envoi.','Unable to read server state. Nothing was sent again.');}finally{busy=false;}}
	$effect(()=>{const pid=projectId;if(initialized&&(pid!==loadedProject||instanceId!==loadedInstance))void initialize(pid);});
	$effect(()=>{if(!responses.some((item:any)=>item.id===selectedMessageId))selectedMessageId=responses.at(-1)?.id||'';});
	onMount(()=>{try{const value=JSON.parse(localStorage.getItem(seenKey())||'null');if(value?.since>0)since=value.since;if(value?.seen&&typeof value.seen==='object')seen=value.seen;}catch{}saveSeen();initialized=true;void initialize(projectId);});
</script>

<section class="project-workspace" aria-label={tr('Activité et livrables','Activity and saved outputs')}>
	<header><div><h2>{tr('Espace du projet','Project workspace')}</h2><p>{tr('Retrouve les réponses, les copies et les changements de fichiers.','Find responses, saved copies and file changes.')}</p></div><Button variant="outline" disabled={loading||busy} onclick={()=>void refresh()}><RefreshCw size={15}/>{tr('Actualiser','Refresh')}</Button></header>
	<nav aria-label={tr('Rubriques de l’espace','Workspace sections')}><Button variant={tab==='activity'?'secondary':'ghost'} onclick={()=>tab='activity'}><Activity size={15}/>{tr('Activité','Activity')}{#if events.filter(isUnread).length}<span class="count">{events.filter(isUnread).length}</span>{/if}</Button><Button variant={tab==='deliverables'?'secondary':'ghost'} onclick={()=>tab='deliverables'}><Archive size={15}/>{tr('Livrables','Saved outputs')}</Button><Button variant={tab==='actions'?'secondary':'ghost'} onclick={()=>tab='actions'}><FileCheck size={15}/>{tr('Actions et versions','Actions and versions')}</Button><Button variant={tab==='trash'?'secondary':'ghost'} onclick={()=>tab='trash'}><Trash2 size={15}/>{tr('Corbeille','Trash')}</Button>{#if onImages}<Button variant="ghost" onclick={onImages}><Image size={15}/>{tr('Galerie images','Image gallery')}</Button>{/if}</nav>
	{#if failure}<p class="feedback failure" role="alert">{failure}</p>{/if}{#if notice}<p class="feedback" role="status">{notice}</p>{/if}{#if partial}<p class="feedback">{partial}</p>{/if}
	{#if pending}<div class="feedback pending"><span>{tr('Une action attend confirmation. Aucun nouvel effet ne sera envoyé avant relecture.','An action awaits confirmation. No new effect will be sent before checking the server.')}</span><Button variant="outline" disabled={busy} onclick={()=>void recover()}>{tr('Vérifier l’action','Check action')}</Button></div>{/if}
	{#if tab==='activity'}<div class="section-heading"><h3>{tr('Réponses terminées pendant ton absence','Responses completed while you were away')}</h3><Button variant="ghost" size="sm" onclick={markAll}>{tr('Tout marquer comme lu','Mark all as read')}</Button></div>
		{#if !events.length}<p class="empty">{tr('Aucune activité terminée pour le moment.','No completed activity yet.')}</p>{/if}
		{#each events as event(event.id)}<article class="entry" class:unread={isUnread(event)}><div><strong>{event.chatName||tr('Conversation','Conversation')}</strong><p>{event.projectName} · {date(event.finishedAt)} · {outcome(event.outcome)}</p>{#if isUnread(event)}<span class="unread-label">{tr('Non lu','Unread')}</span>{/if}</div><div class="buttons"><Button variant="outline" size="sm" onclick={()=>{markRead(event);void onNavigate?.({projectId:event.projectId,id:event.chatId,messageId:event.messageId});}}>{tr('Ouvrir la réponse','Open response')}</Button>{#if isUnread(event)}<Button variant="ghost" size="sm" onclick={()=>markRead(event)}>{tr('Marquer comme lu','Mark as read')}</Button>{/if}</div></article>{/each}
		{#if activityCursor}<Button variant="outline" disabled={loading} onclick={()=>void loadActivity(true).catch((error:any)=>failure=error.message)}>{tr('Activité plus ancienne','Older activity')}</Button>{/if}
	{:else if tab==='deliverables'}
		{#if responses.length}<form class="capture" onsubmit={event=>{event.preventDefault();const message=responses.find((item:any)=>item.id===selectedMessageId);if(message)void pin(message);}}><h3>{tr('Conserver une réponse de cette conversation','Save a response from this conversation')}</h3><label for="workspace-message">{tr('Réponse','Response')}</label><select id="workspace-message" bind:value={selectedMessageId} disabled={busy}>{#each responses as message}<option value={message.id}>{message.text.slice(0,100)}</option>{/each}</select><label for="workspace-pin-title">{tr('Titre de la copie (facultatif)','Copy title (optional)')}</label><input id="workspace-pin-title" bind:value={pinTitle} maxlength="120" disabled={busy}/><Button type="submit" disabled={busy||!!pending||!selectedMessageId}>{tr('Conserver la réponse','Save response')}</Button></form>{/if}
		{#if !deliverables.length}<p class="empty">{tr('Aucune copie conservée dans ce projet.','No saved copies in this project.')}</p>{/if}
		<div class="copies-layout"><div>{#each deliverables as item(item.id)}<article class="entry"><div><strong>{item.title}</strong><p>{item.kind==='file'?tr('Copie de fichier','File copy'):tr('Copie de réponse','Response copy')} · {date(item.createdAt)}</p><p>{item.origin?.chatName}</p></div><Button variant="outline" size="sm" disabled={busy} onclick={()=>void openCopy(item)}>{tr('Ouvrir la copie','Open copy')}</Button></article>{/each}</div>
		{#if detail}<section class="copy-detail" aria-label={tr('Détail du livrable','Saved output details')}><div class="section-heading"><h3>{detail.title}</h3><Button variant="ghost" size="sm" onclick={()=>detail=null}>{tr('Fermer','Close')}</Button></div><p>{detail.sourceStatus==='changed'?tr('Le fichier du PC a changé ; cette copie reste figée.','The PC file changed; this copy stays unchanged.'):detail.sourceStatus==='missing'?tr('Le fichier source est absent ; cette copie reste disponible.','The source file is missing; this copy remains available.'):tr('Copie indépendante conservée dans le projet.','Independent copy saved in the project.')}</p>{#if detail.text!==undefined}<pre>{detail.text}</pre>{#if detail.textTruncated}<p>{tr('Aperçu limité ; le téléchargement conserve le contenu complet.','Limited preview; the download contains the full content.')}</p>{/if}{/if}
			<div class="buttons"><a href={query('/api/deliverable/download',{projectId,id:detail.id})} download>{tr('Télécharger la copie','Download copy')}</a><Button variant="outline" size="sm" onclick={()=>void onNavigate?.({projectId,id:detail.origin.chatId,messageId:detail.origin.messageId})}>{tr('Voir l’origine','View source')}</Button></div>
			<form onsubmit={event=>{event.preventDefault();void renameCopy();}}><label for="workspace-copy-title">{tr('Titre du livrable','Saved output title')}</label><input id="workspace-copy-title" bind:value={detailTitle} maxlength="120" disabled={busy}/><div class="buttons"><Button type="submit" variant="outline" disabled={busy||!!pending||!detailTitle.trim()}>{tr('Renommer la copie','Rename copy')}</Button><Button variant="ghost" disabled={busy||!!pending} onclick={()=>void removeCopy()}>{tr('Retirer la copie','Remove copy')}</Button></div></form><p class="hash">SHA-256 : {detail.hash}</p>
		</section>{/if}</div>
	{:else if tab==='trash'}
		<p class="section-note">{tr('Les fichiers retirés restent téléchargeables. Une restauration ne remplace jamais un fichier existant.','Removed files remain downloadable. Restoration never replaces an existing file.')}</p>
		{#if !trash.length}<p class="empty">{tr('La corbeille de ce projet est vide.','This project’s trash is empty.')}</p>{/if}
		{#each trash as item(item.id)}<article class="entry"><div><strong>{item.path||item.name}</strong><p>{date(item.savedAt)} · {item.status==='available'?tr('Copie disponible','Copy available'):tr('Copie endommagée','Damaged copy')}</p></div>{#if item.status==='available'}<div class="buttons"><a href={query('/api/files/trash/download',{projectId,backupId:item.id})} download>{tr('Télécharger','Download')}</a><Button variant="outline" size="sm" disabled={busy||!!pending} onclick={()=>void restoreTrash(item)}>{tr('Restaurer le fichier','Restore file')}</Button></div>{/if}</article>{/each}
	{:else}
		{#if !chat?.id}<p class="empty">{tr('Ouvre une conversation pour consulter ses actions et versions.','Open a conversation to view its actions and versions.')}</p>{/if}
		{#if !actionRows.length&&!uncertainWrites.length}<p class="empty">{tr('Aucune action dans les messages chargés.','No actions in the loaded messages.')}</p>{/if}
		{#each uncertainWrites as row}<article class="entry uncertain"><div><strong>{tr('Écriture au résultat incertain','Write result uncertain')}</strong><p>{row.intent.path}</p><p>{row.intent.message||row.intent.backupNotice||tr('Relis le fichier et compare les copies avant toute nouvelle modification.','Read the file and compare copies before changing it again.')}</p><div class="buttons">{#each row.intent.backupCandidates||[] as backup}<a href={query('/api/files/backup/download',{projectId,backupId:backup.id})} download>{tr('Copie vérifiée','Verified copy')} · {date(backup.savedAt)}</a>{/each}</div></div></article>{/each}
		{#each actionRows as row,index(row.action.id||'historical-'+index)}<article class="action-entry"><h3>{row.action.message||row.action.name||tr('Action','Action')}</h3><p>{row.action.path}{row.action.destination?' → '+row.action.destination:''}</p>{#if row.historical||row.action.historical||row.message.fromFork}<p>{tr('Journal historique : les écritures, validations et restaurations ne sont pas rejouées.','Historical record: writes, approvals and restorations are not replayed.')}</p>{/if}{#if row.action.projectId&&row.action.projectId!==projectId}<p>{tr('Action d’un autre projet : consultation uniquement.','Action from another project: view only.')}</p>{/if}
			{#if row.action.stdout||row.action.stderr}<details><summary>{tr('Sortie du script','Script output')}</summary><pre>{row.action.stdout||''}{row.action.stderr?'\n'+row.action.stderr:''}</pre></details>{/if}
			{#if row.action.outbound}<details><summary>{tr('Données envoyées','Sent data')}</summary><pre>{JSON.stringify(row.action.outbound,null,2)}</pre></details>{/if}
			<div class="buttons">{#if safeAction(row)&&['write_project_file','replace_project_text'].includes(row.action.name)&&!row.action.restored}<Button size="sm" variant="outline" disabled={busy||!!pending} onclick={()=>void pin(row.message,row.action)}>{tr('Conserver le fichier','Save file copy')}</Button>{/if}{#if safeAction(row)&&row.action.backupId&&row.action.hash}<Button size="sm" variant="outline" disabled={busy} onclick={()=>void compare(row)}>{tr('Comparer les versions','Compare versions')}</Button>{/if}{#if safeAction(row)&&(row.action.backupId&&row.action.hash||row.action.trashId)}<Button size="sm" variant="outline" disabled={busy||!!pending||row.action.restored} onclick={()=>void restoreAction(row)}>{row.action.restored?tr('Fichier rétabli','File restored'):tr('Rétablir la version précédente','Restore previous version')}</Button>{/if}</div>
			{#if diffs[row.action.id]}{@const diff=diffs[row.action.id]}<div class="version-comparison"><h4>{diff.label||tr('Comparaison vérifiée','Verified comparison')}</h4>{#if diff.status==='comparable'}<div><section><h5>{tr('Avant','Before')}</h5><pre>{diff.before.text}</pre></section><section><h5>{tr('Après','After')}</h5><pre>{diff.after.text}</pre></section></div>{:else}<p>{tr('Une version ultérieure est présente ; aucune comparaison historique présentée comme actuelle.','A later version is present; the historical comparison is not shown as the current version.')}</p>{/if}</div>{/if}
		</article>{/each}
	{/if}
</section>

<style>
